(window.EXAM_BANK=window.EXAM_BANK||[]).push(
{id:'dc-s01',course:'data-communication',src:['dc09',4],type:'short',q:'링크 계층의 패킷(2계층 패킷)을 부르는 이름은?',answer:['프레임','frame'],why:'9주차 4쪽: 2계층 패킷 = 프레임(frame), datagram을 캡슐화.'},
{id:'dc-s02',course:'data-communication',src:['dc09',8],type:'short',q:'링크 계층이 주로 구현되는 장치(약어 3글자)는?',answer:['NIC','network interface card','네트워크 인터페이스 카드','어댑터'],why:'9주차 8쪽: 어댑터(NIC) 또는 칩.'},
{id:'dc-s03',course:'data-communication',src:['dc09',15],type:'short',q:'D = 101110, G = 1001일 때 CRC 나머지 R은?',answer:['011'],why:'101110000 ÷ 1001 (modulo 2)의 나머지 = 011.'},
{id:'dc-s04',course:'data-communication',src:['dc09',15],type:'short',q:'D = 1101, G = 101일 때 CRC 나머지 R은? (r = 2)',answer:['10'],why:'110100 ÷ 101 (modulo 2): 110⊕101 → 011100, 111⊕101 → 001000, 100⊕101 → 000010 → 나머지 10. 전송 110110, 검산 110110 ÷ 101 나머지 00.'},
{id:'dc-s05',course:'data-communication',src:['dc09',14],type:'short',q:'CRC 생성자 G가 r+1비트일 때 반드시 검출할 수 있는 burst 오류의 최대 길이는? (r을 사용해 답)',answer:['r+1','r + 1','r+1비트'],why:'9주차 14쪽: 모든 r+1 bit 이하의 burst 오류를 검출.'},
{id:'dc-s06',course:'data-communication',src:['dc09',26],type:'short',q:'노드가 매우 많을 때 slotted ALOHA의 최대 효율은? (소수 둘째 자리)',answer:['0.37','1/e','37%'],why:'9주차 26쪽: max efficiency = 1/e ≈ .37.'},
{id:'dc-s07',course:'data-communication',src:['dc09',28],type:'short',q:'노드가 매우 많을 때 순수 ALOHA의 최대 효율은? (소수 둘째 자리)',answer:['0.18','1/(2e)','1/2e','18%'],why:'9주차 28쪽: 1/(2e) = .18.'},
{id:'dc-s08',course:'data-communication',src:['dc09',33],type:'short',q:'Ethernet CSMA/CD에서 4번째 연속 충돌 후 K를 고르는 범위의 최댓값은?',answer:['15'],why:'m = 4 → {0, …, 2^4 − 1} = {0, …, 15}.'},
{id:'dc-s09',course:'data-communication',src:['dc09',33],type:'short',q:'이진 백오프에서 K를 골랐을 때 기다리는 시간은 K × 몇 비트 시간인가?',answer:['512','512비트','512 비트 시간'],why:'9주차 33쪽: K·512 bit 시간 동안 기다림.'},
{id:'dc-s10',course:'data-communication',src:['dc09',42],type:'short',q:'대부분의 LAN에서 MAC 주소는 몇 비트인가?',answer:['48','48비트'],why:'9주차 42쪽: 48 bit MAC 주소.'},
{id:'dc-s11',course:'data-communication',src:['dc09',46],type:'short',q:'ARP 질의 프레임의 목적지 MAC 주소는?',answer:['FF-FF-FF-FF-FF-FF','FFFFFFFFFFFF','ff-ff-ff-ff-ff-ff','ff:ff:ff:ff:ff:ff'],why:'9주차 46쪽: 브로드캐스트 주소.'},
{id:'dc-s12',course:'data-communication',src:['dc09',45],type:'short',q:'ARP 테이블 항목의 TTL은 보통 몇 분인가?',answer:['20','20분'],why:'9주차 45쪽: 보통 20분.'},
{id:'dc-s13',course:'data-communication',src:['dc09',55],type:'short',q:'Ethernet 프리앰블의 마지막 바이트 비트 패턴은?',answer:['10101011'],why:'9주차 55쪽: 10101010 7바이트 + 10101011 1바이트.'},
{id:'dc-s14',course:'data-communication',src:['dc09',74],type:'short',q:'802.1Q 태그의 TPID(Tag Protocol Identifier) 값은? (16진수)',answer:['81-00','8100','0x8100','81 00'],why:'9주차 74쪽: value 81-00.'},
{id:'dc-s15',course:'data-communication',src:['dc09',74],type:'short',q:'802.1Q 태그의 VLAN ID 필드는 몇 비트인가?',answer:['12','12비트'],why:'9주차 74쪽: 12 bit VLAN ID field.'},
{id:'dc-s16',course:'data-communication',src:['dc09',80],type:'short',q:'진입 MPLS 라우터가 하류 라우터의 MPLS 포워딩을 설정할 때 쓰는 신호 프로토콜은?',answer:['RSVP-TE','RSVPTE','RSVP TE'],why:'9주차 80쪽.'},
{id:'dc-s17',course:'data-communication',src:['dc09',40],type:'short',q:'802.11 무선 LAN이 사용하는 MAC 프로토콜은?',answer:['CSMA/CA','CSMACA'],why:'9주차 40쪽: 802.11에 사용되는 CSMA/CA.'},
{id:'dc-s18',course:'data-communication',src:['dc09',12],type:'short',q:'데이터 1011001에 짝수 parity 비트를 붙이면 parity 비트 값은?',answer:['0'],why:'1의 개수가 4개(짝수)이므로 parity 비트는 0.'},
{id:'dc-t01',course:'data-communication',src:['dc09',11],type:'tf',q:'오류 검출 비트(EDC)를 사용하면 모든 비트 오류를 반드시 검출할 수 있다.',answer:false,why:'9주차 11쪽: 오류 검출을 100% 신뢰할 수 있는 것은 아니다.'},
{id:'dc-t02',course:'data-communication',src:['dc09',12],type:'tf',q:'2차원 비트 parity는 단일 비트 오류를 검출하고 정정할 수 있다.',answer:true,why:'9주차 12쪽.'},
{id:'dc-t03',course:'data-communication',src:['dc09',21],type:'tf',q:'TDMA에서는 활성 노드가 하나뿐이면 그 노드가 채널 전체 속도 R을 사용할 수 있다.',answer:false,why:'고정 슬롯만 쓰므로 R/N만 사용합니다(9주차 21, 35쪽).'},
{id:'dc-t04',course:'data-communication',src:['dc09',30],type:'tf',q:'CSMA를 사용하면 전파 지연이 있어도 충돌이 일어나지 않는다.',answer:false,why:'9주차 30쪽: 전파 지연 때문에 충돌은 여전히 생길 수 있다.'},
{id:'dc-t05',course:'data-communication',src:['dc09',31],type:'tf',q:'충돌 감지(CD)는 무선 LAN보다 유선 LAN에서 쉽다.',answer:true,why:'9주차 31쪽.'},
{id:'dc-t06',course:'data-communication',src:['dc09',44],type:'tf',q:'IP 주소는 평면 구조라 노드를 다른 서브넷으로 옮겨도 그대로 쓸 수 있다.',answer:false,why:'평면 구조로 이동성이 있는 것은 MAC 주소입니다. IP는 계층적이라 서브넷에 의존합니다(9주차 44쪽).'},
{id:'dc-t07',course:'data-communication',src:['dc09',46],type:'tf',q:'ARP 질의에 대한 응답은 질의한 노드에게 유니캐스트로 보내진다.',answer:true,why:'9주차 46쪽: B는 A에게 자신의 MAC 주소를 응답, 프레임이 A의 MAC 주소로 전송(unicast).'},
{id:'dc-t08',course:'data-communication',src:['dc09',50],type:'tf',q:'datagram이 라우터를 지나 다른 LAN으로 갈 때 프레임의 MAC 주소는 바뀌지만 datagram의 출발지·목적지 IP 주소는 그대로이다.',answer:true,why:'9주차 48~51쪽.'},
{id:'dc-t09',course:'data-communication',src:['dc09',57],type:'tf',q:'Ethernet 수신 NIC는 프레임을 정상 수신하면 송신 NIC에 ACK를 보낸다.',answer:false,why:'Ethernet은 비신뢰적이라 ACK/NAK를 보내지 않습니다(9주차 57쪽).'},
{id:'dc-t10',course:'data-communication',src:['dc09',63],type:'tf',q:'스위치는 프레임의 목적지 MAC 주소를 이용해 자가 학습한다.',answer:false,why:'출발지 MAC 주소와 들어온 인터페이스를 학습합니다(9주차 63쪽).'},
{id:'dc-t11',course:'data-communication',src:['dc09',69],type:'tf',q:'스위치와 라우터는 모두 저장 후 전달(store-and-forward) 장치이다.',answer:true,why:'9주차 69쪽.'},
{id:'dc-t12',course:'data-communication',src:['dc09',77],type:'tf',q:'MPLS 라우터는 레이블 값만으로 출력 인터페이스를 결정하며 IP 주소를 검사하지 않는다.',answer:true,why:'9주차 77쪽.'},
{id:'dc-c01',course:'data-communication',src:['dc09',64],type:'code',q:'빈 스위치 테이블에서 A(포트 1)가 C(포트 3)로 프레임을 보낸 직후 스위치 테이블에 생기는 항목을 "MAC 포트" 형식으로 쓰시오.',code:'스위치 포트: A=1, B=2, C=3, D=4\n프레임 1: A → C',answer:['A 1','A1','A,1'],why:'출발지 A와 들어온 포트 1만 학습합니다. C는 아직 모릅니다(flood).'},
{id:'dc-c02',course:'data-communication',src:['dc09',64],type:'code',q:'이어서 C가 A에게 응답하면, 스위치가 이 프레임을 내보내는 포트 번호는?',code:'스위치 테이블: A → 1\n프레임 2: C(포트 3) → A',answer:['1','1번'],why:'A의 위치(포트 1)를 알고 있으므로 1번 포트로만 전달합니다. 동시에 C → 3을 학습합니다.'},
{id:'dc-c03',course:'data-communication',src:['dc09',81],type:'code',q:'자료의 MPLS 표에서 R4가 레이블 10을 붙여 보낸 A행 패킷이 R3을 지난 뒤 갖는 레이블은?',code:'R3: in 10 → out 6, A, if 1\n    in 12 → out 9, D, if 0',answer:['6'],why:'R3 테이블: 입력 10 → 출력 6.'},
{id:'dc-c04',course:'data-communication',src:['dc09',13],type:'code',q:'16비트 단어 1111 1111 0000 0000 과 0000 0001 0000 0001 의 인터넷 checksum은? (16비트, 공백 없이)',code:'  1111111100000000\n+ 0000000100000001\n= ?  (자리올림은 다시 더함)\nchecksum = 합의 1의 보수',answer:['1111111111111101'],why:'합 0xFF00 + 0x0101 = 1 0000 0000 0000 0001 → 올림 1을 다시 더해 0000 0000 0000 0010 → 1의 보수 1111 1111 1111 1101.'}
);
